INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(94432, 'ruRU', 'Расскажи подробнее...', '', 24330),
(94433, 'ruRU', 'Ты посмел явиться в МОЙ ЛАГЕРЬ? Я с огромным удовольствием разорву тебя на куски... кусок за куском.', '', 24330),
(94434, 'ruRU', 'Идёмте, герои! Встаньте рядом со мной и обрушьте свою силу!', '', 24330),
(94436, 'ruRU', 'Охота продолжается...', '', 24330),
(94438, 'ruRU', 'Бойся ночи!', '', 24330),
(94440, 'ruRU', 'Даже злодеи боятся того, что таится за тенями...', '', 24330),
(94441, 'ruRU', 'Слава тебе, Верховный лорд.', '', 24330),
(94442, 'ruRU', 'Я слышал, что Верховный лорд $p убил Архимонда голыми руками!', '', 24330),
(94443, 'ruRU', 'А ты знал, что Верховный лорд однажды убил пятьсот демонов одним ударом?', '', 24330),
(94444, 'ruRU', 'Я подслушал, как защитник Бачи говорил, что Верховный лорд может возвращаться из мёртвых.', '', 24330),
(94445, 'ruRU', 'Я читал, что Верховный лорд $p убил Рагнароса Повелителя Огня... дважды!', '', 24330),
(94446, 'ruRU', 'Мы продолжим тренировку позже, $p. Не погибни там.', '', 24330),
(94447, 'ruRU', 'Думаешь, меня выберут на следующую вылазку? Я слышал, Верховный лорд разрешает оставлять часть добычи!', '', 24330),
(94448, 'ruRU', 'Все паладины мира объединились под одной крышей... у Легиона нет шансов.', '', 24330),
(94449, 'ruRU', 'Думаешь, Верховный лорд $p заметил, как усердно я тренируюсь в последнее время? Мне так хочется впечатлить $Ghim:her;!', '', 24330),
(94450, 'ruRU', 'Думаешь, Верховный лорд $p — полубог?', '', 24330),
(94451, 'ruRU', 'Верховный лорд приближается. Салют!', '', 24330),
(94452, 'ruRU', 'Это существо — вождь твоей Орды, $n? Он мне нравится. Он не боится дерзких действий, но предпочитает сперва добиться согласия среди своего народа, прежде чем действовать.$b$bНам понадобится смелая стратегия, если мы хотим напасть на джунгли Танаан. Твоему вождю повезло, что ты у него под рукой.', '', 24330),
(94453, 'ruRU', '|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|tДавай сделаем это! Нагрей лей-камень в горне, как и раньше.', '', 24330),
(94454, 'ruRU', '|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|tТеперь попросим мага Кирин-Тора тщательно охладить металл. Загляни на подставку для тортов у моего магазина.', '', 24330),
(94456, 'ruRU', '|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|tДавай, возвращайся сюда! Нам нужно ещё раз нагреть и снова охладить металл.', '', 24330),
(94458, 'ruRU', '|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|tОчень хорошо. Теперь посмотрим, помнишь ли ты остальное.', '', 24330),
(94459, 'ruRU', 'Я продолжу размышлять, как улучшить наши техники работы с лей-камнем, $n. Твоё обучение ещё не закончено.', '', 24330),
(94460, 'ruRU', 'Этот мир будет сожжён дотла!', '', 24330),
(94461, 'ruRU', 'Покорись своему уничтожению!', '', 24330),
(94462, 'ruRU', 'Никого не пощадят!', '', 24330),
(94463, 'ruRU', 'Ты понятия не имеешь... с чем столкнулся...', '', 24330),
(94464, 'ruRU', 'Тебе не остановить нас всех.', '', 24330),
(94465, 'ruRU', 'Легион вечен!', '', 24330),
(94466, 'ruRU', 'Ты... умрёшь...', '', 24330),
(94467, 'ruRU', 'Орда на тебя рассчитывает, командир. Найди нам корабела, чтобы мы могли окружить Танаан!', '', 24330);
